package edu.pe.cibertec.saibm.membresia.infrastructure.messaging;
import org.springframework.amqp.rabbit.core.RabbitTemplate; import org.springframework.data.domain.PageRequest; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component; import org.springframework.transaction.annotation.Transactional; import edu.pe.cibertec.saibm.membresia.infrastructure.persistence.*;
@Component public class OutboxPublisher {private final OutboxJpaRepository outbox;private final RabbitTemplate rabbit;public OutboxPublisher(OutboxJpaRepository o,RabbitTemplate r){outbox=o;rabbit=r;}@Scheduled(fixedDelayString="${membresia.outbox.delay-ms:500}")@Transactional public void publish(){for(var e:outbox.pending(PageRequest.of(0,50))){rabbit.convertAndSend(MembershipRabbitConfig.EXCHANGE,e.getEventType(),e.getPayloadJson());e.published();outbox.save(e);}}}
